changeSet.sql:
CREATE UNIQUE INDEX uk_model_release_candidate_active_plan
    ON modeling_model_release_candidate (tenant_id, plan_id)
    WHERE status NOT IN ('REJECTED', 'ROLLED_BACK', 'STALE');

rollback.sql:
DO $$
BEGIN
    LOCK TABLE modeling_model_release_candidate IN ACCESS EXCLUSIVE MODE;
    IF EXISTS (SELECT 1 FROM modeling_model_release_candidate) THEN
        RAISE EXCEPTION 'ROLLBACK_BLOCKED_MODEL_RELEASE_CANDIDATE_DATA_EXISTS';
    END IF;
END $$;
